	t.Run("GetID", func(t *testing.T) {
		t.Parallel()
		// Arrange
		obj := &Integration{}
		var value string
		obj.ID = &value

		// Act & Assert
		assert.Equal(t, value, obj.GetID(), "getter should dereference and return the value")
	})

