func TestGettersLogDate(t *testing.T) {
	t.Run("GetString", func(t *testing.T) {
		t.Parallel()
		// Arrange
		obj := &LogDate{}
		var expected string
		obj.String = expected

		// Act & Assert
		assert.Equal(t, expected, obj.GetString(), "getter should return the property value")
	})

	t.Run("GetString_NilReceiver", func(t *testing.T) {
		t.Parallel()
		var obj *LogDate
		// Should not panic - getters should handle nil receiver gracefully
		defer func() {
			if r := recover(); r != nil {
				t.Errorf("Getter panicked on nil receiver: %v", r)
			}
		}()
		_ = obj.GetString() // Should return zero value
	})

	t.Run("GetLogDateObject", func(t *testing.T) {
		t.Parallel()
		// Arrange
		obj := &LogDate{}
		var expected LogDateObject
		obj.LogDateObject = expected

		// Act & Assert
		assert.Equal(t, expected, obj.GetLogDateObject(), "getter should return the property value")
	})

	t.Run("GetLogDateObject_NilReceiver", func(t *testing.T) {
		t.Parallel()
		var obj *LogDate
		// Should not panic - getters should handle nil receiver gracefully
		defer func() {
			if r := recover(); r != nil {
				t.Errorf("Getter panicked on nil receiver: %v", r)
			}
		}()
		_ = obj.GetLogDateObject() // Should return zero value
	})

}

